const messages = [{ role: "user", content: task }];
for (let turn = 0; turn < MAX_TURNS; turn++) {
  const res = await callModel({ messages, tools });
  messages.push({ role: "assistant", content: res.content });
  if (res.stop_reason !== "tool_use") return res; // ตอบเสร็จแล้ว
  const results = [];
  for (const call of res.content.filter((b) => b.type === "tool_use"))
    results.push({ type: "tool_result", tool_use_id: call.id,
                   content: await runTool(call.name, call.input) });
  messages.push({ role: "user", content: results });
}
throw new Error("ถึง MAX_TURNS ก่อนงานเสร็จ");

