  "name": "search_orders",
  "description": "ค้นคำสั่งซื้อของลูกค้าด้วยอีเมล ใช้เมื่อลูกค้าถามสถานะหรือประวัติคำสั่งซื้อ คืนรายการล่าสุดก่อน แต่ละรายการมีเลขคำสั่งซื้อ วันที่ สถานะ และยอดรวม",
  "input_schema": {
    "type": "object",
    "properties": {
      "email": {
        "type": "string",
        "description": "อีเมลที่ลูกค้าใช้สั่งซื้อ"
      },
      "status": {
        "type": "string",
        "enum": ["pending", "shipped", "delivered"],
        "description": "กรองตามสถานะ ไม่ระบุ = ทุกสถานะ"
      },
      "limit": {
        "type": "integer",
        "minimum": 1,
        "maximum": 50,
        "default": 10,
        "description": "จำนวนรายการสูงสุดที่คืน"
      }
    },
    "required": ["email"]
  }
}
